import json
from datetime import datetime

def process_memory(memory, updates):
    # Find all updates that are relevant to this memory
    relevant_updates = [u for u in updates if u['id'] in memory['text'] or u['id'] in memory['id']]

    # Check if any of the relevant updates have changed the memory
    for u in relevant_updates:
        # Check if the update is older than the memory
        if datetime.strptime(u['observed'], '%Y-%m-%d') < datetime.strptime(memory['observed'], '%Y-%m-%d'):
            continue

        # Check if the update has changed the memory
        if u['id'] in memory['text']:
            if u['text'] == 'withdrawn' or u['text'] == 'retracted':
                return 'withdraw'
            elif u['text'] == 'replaced':
                return 'recompute'
            elif u['text'] == 'doubtful':
                return 'uncertain'

    # If no updates have changed the memory, keep it
    return 'keep'

def process_memories(memories, updates):
    # Process each memory
    for memory in memories:
        action = process_memory(memory, updates)
        if action != 'keep':
            print(json.dumps({'id': memory['id'], 'action': action}))

